mapper.select:
SELECT sr.id, sr.user_id, u.nickname, sr.sign_date, sr.consecutive_day, sr.reward_point, sr.create_time FROM sign_in_record sr LEFT JOIN user_info u ON sr.user_id = u.id AND u.del_flag = '0'
AND u.nickname LIKE CONCAT('%', #{nickname}, '%')
AND sr.sign_date >= #{beginDate}
AND sr.sign_date <= #{endDate}
ORDER BY sr.sign_date DESC
